"""The 32 voices of FM-DX's INTERNAL bank, made for PATCHWERK: four operators each, in the TX81Z's terms (algorithm 1-8, feedback 0-7, per operator
the coarse ratio, output level 0-99, attack, decay 1, decay 2, release 1-15, sustain level 0-15 (15: none), wave 0-7 (W1-W8), detune 0-6 (3: none)).
OP1 is the output of algorithm 1; OP4 the first of the chain and the one with the feedback."""


def op(F=1.0, out=0, ar=31, d1r=0, d1l=15, d2r=0, rr=7, osw=0, det=3, rs=0, ls=0, ame=0, egs=0, fine=0, fix=0, fixrg=0, ebs=0, kvs=0):
    return dict(F=F, out=out, ar=ar, d1r=d1r, d1l=d1l, d2r=d2r, rr=rr, osw=osw, det=det, rs=rs, ls=ls, ame=ame, egs=egs, fine=fine, fix=fix, fixrg=fixrg, ebs=ebs, kvs=kvs)


def lfo(speed=35, delay=0, pmd=0, amd=0, pms=0, ams=0, wave=2, sync=0):
    return dict(speed=speed, delay=delay, pmd=pmd, amd=amd, pms=pms, ams=ams, wave=wave, sync=sync)


def V(name, alg, fb, ops, l=None, trps=24):
    return dict(name=name, alg=alg, fb=fb, ops=ops, lfo=l or lfo(), trps=trps)


